CREATE TABLE engine_review_decisions(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES engine_tasks(id), subject_kind TEXT NOT NULL CHECK(subject_kind IN ('finding','change')), subject_id TEXT NOT NULL, decision TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL, authority_source TEXT, supersedes_id TEXT REFERENCES engine_review_decisions(id), created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_signoffs(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES engine_tasks(id), run_id TEXT NOT NULL, report_hash TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('approve','withhold')), actor TEXT NOT NULL, reason TEXT NOT NULL, supersedes_id TEXT REFERENCES engine_signoffs(id), created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_retests(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES engine_tasks(id), original_run_id TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES engine_jobs(id), actor TEXT NOT NULL, reason TEXT NOT NULL, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE engine_expectation_revisions(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES engine_tasks(id), requirement_key TEXT NOT NULL, previous_story_id TEXT NOT NULL, new_story_id TEXT NOT NULL, previous_text TEXT NOT NULL, new_text TEXT NOT NULL, authority_source TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL, parent_revision_id TEXT REFERENCES engine_expectation_revisions(id), created_at INTEGER NOT NULL) STRICT;
CREATE TRIGGER engine_review_no_update BEFORE UPDATE ON engine_review_decisions BEGIN SELECT RAISE(ABORT,'Immutable review decision'); END;
CREATE TRIGGER engine_review_no_delete BEFORE DELETE ON engine_review_decisions BEGIN SELECT RAISE(ABORT,'Immutable review decision'); END;
CREATE TRIGGER engine_signoff_no_update BEFORE UPDATE ON engine_signoffs BEGIN SELECT RAISE(ABORT,'Immutable signoff'); END;
CREATE TRIGGER engine_signoff_no_delete BEFORE DELETE ON engine_signoffs BEGIN SELECT RAISE(ABORT,'Immutable signoff'); END;
CREATE TRIGGER engine_expectation_no_update BEFORE UPDATE ON engine_expectation_revisions BEGIN SELECT RAISE(ABORT,'Immutable expectation revision'); END;
CREATE TRIGGER engine_expectation_no_delete BEFORE DELETE ON engine_expectation_revisions BEGIN SELECT RAISE(ABORT,'Immutable expectation revision'); END;
